import{_ as e,o as a,c as i,a3 as d}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"专题进阶总览","description":"","frontmatter":{"title":"专题进阶总览"},"headers":[],"relativePath":"frontend/topics/index.md","filePath":"frontend/topics/index.md","lastUpdated":1784378817000}'),r={name:"frontend/topics/index.md"};function l(o,t,n,s,h,c){return a(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="专题进阶" tabindex="-1">专题进阶 <a class="header-anchor" href="#专题进阶" aria-label="Permalink to &quot;专题进阶&quot;">​</a></h1><p>专题进阶收录能够独立发展为专业方向、但并非所有前端项目都必须深入掌握的知识领域。它既不是核心知识的“困难版”，也不是工程体系未能归类内容的集合；每个专题都应具备自己的概念模型、技术栈、实践场景和能力边界。</p><p>学习专题时，应先明确它解决的产品问题，再掌握基础模型、关键 API、典型实现和工程约束。只有能够把专项技术接入真实应用，并处理性能、测试、安全和可维护性问题，才算完成从知识理解到专业能力的转换。</p><h2 id="专题地图" tabindex="-1">专题地图 <a class="header-anchor" href="#专题地图" aria-label="Permalink to &quot;专题地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>关注范围</th><th>典型应用</th></tr></thead><tbody><tr><td><a href="/frontend/topics/algorithms/">数据结构与算法</a></td><td>复杂度、线性结构、哈希、树、图、搜索与动态规划</td><td>依赖分析、缓存、调度、虚拟列表、DOM 与 AST 处理</td></tr><tr><td><a href="/frontend/topics/design-patterns/">前端设计模式</a></td><td>对象协作、事件、状态、组件组合、插件与重构</td><td>建立可复用设计语言，控制变化和依赖方向</td></tr><tr><td><a href="/frontend/topics/graphics/">可视化与图形</a></td><td>SVG、Canvas、WebGL、WebGPU、图表、3D 与 GIS</td><td>数据大屏、图形编辑器、地图、游戏和三维场景</td></tr><tr><td><a href="/frontend/topics/editors-collaboration/">富文本编辑器与实时协同</a></td><td>文档模型、输入系统、插件、OT、CRDT 与协同协议</td><td>富文本编辑器、多人文档、白板和结构化内容工具</td></tr><tr><td><a href="/frontend/topics/media-realtime/">音视频与实时互动</a></td><td>媒体播放、采集、处理、WebRTC、Web Audio 与 WebCodecs</td><td>直播、会议、在线教育、录制和音视频编辑</td></tr><tr><td><a href="/frontend/topics/ast-tooling/">AST 与编译器工具开发</a></td><td>解析、遍历、代码生成、Lint、插件与自动迁移</td><td>工程工具、代码检查、框架编译和大规模重构</td></tr><tr><td><a href="/frontend/topics/cross-platform/pwa">跨端开发</a></td><td>PWA、原生容器、小程序、桌面应用与 Wasm</td><td>在不同终端复用 Web 技术并适配平台能力</td></tr><tr><td><a href="/frontend/topics/ai/llm-applications">AI 应用开发</a></td><td>模型接入、流式 UI、工具调用、评测与降级</td><td>对话助手、生成式界面和智能业务流程</td></tr></tbody></table><h2 id="如何选择专题" tabindex="-1">如何选择专题 <a class="header-anchor" href="#如何选择专题" aria-label="Permalink to &quot;如何选择专题&quot;">​</a></h2><p>专题不要求按目录顺序全部学习。选择顺序应由产品场景和岗位方向决定：</p><ul><li>复杂数据处理、基础设施和面试能力：数据结构与算法。</li><li>大型应用抽象、组件库和框架设计：前端设计模式。</li><li>图表、编辑器、地图、游戏或三维产品：可视化与图形。</li><li>富文本、结构化文档和多人编辑产品：富文本编辑器与实时协同。</li><li>直播、会议、音频处理和媒体编辑产品：音视频与实时互动。</li><li>工程工具、编译插件、代码检查和自动迁移：AST 与编译器工具开发。</li><li>小程序、桌面端、移动容器或离线应用：跨端开发。</li><li>对话、生成、智能工作流和模型集成：AI 应用开发。</li></ul><h2 id="规划中的专题" tabindex="-1">规划中的专题 <a class="header-anchor" href="#规划中的专题" aria-label="Permalink to &quot;规划中的专题&quot;">​</a></h2><p>以下方向具有相对独立的问题模型和工程体系，后续可根据内容建设进度发展为新的专题。当前仅说明其定位，不建立对应分组和章节。</p><ul><li>WebAssembly 与高性能计算：面向图片与音视频处理、压缩解压、几何运算、科学计算、端侧推理以及 Rust、C、C++ 库复用等 CPU 密集型场景，重点研究线性内存、JavaScript 互操作、语言工具链、Worker、线程与 SIMD。普通业务逻辑、DOM 密集型交互和轻量计算通常不需要为此增加工具链与数据传递成本；现有跨端章节只介绍其应用边界。</li><li>浏览器扩展开发：面向网页能力增强、内容摘录、密码与凭证管理、企业工作辅助、开发者工具和跨站工作流，重点处理 Manifest、权限、后台 Service Worker、Content Script、多运行上下文通信和扩展商店发布。它适合需要浏览器级能力或页面注入能力的产品，而不是普通 Web 应用的替代形态。</li><li>本地优先应用与数据同步：面向笔记、任务、知识库、现场作业和弱网环境中的多设备应用，把本地数据库作为主要读写入口，使用户在离线时仍可完整工作，再通过同步协议传播变更并解决冲突。它比一般的离线缓存更关注数据模型、增量同步、一致性、冲突合并、Schema 演进和故障恢复。</li><li>Web 自动化与页面采集：面向端到端测试、业务巡检、页面截图、重复操作自动化、数据迁移和公开信息采集，通过受控浏览器完成导航、交互、网络观察和结构化数据提取。使用时应优先选择正式 API，并把访问权限、站点规则、版权、隐私、限速和运行稳定性作为方案的一部分。</li></ul><h2 id="与其他模块的边界" tabindex="-1">与其他模块的边界 <a class="header-anchor" href="#与其他模块的边界" aria-label="Permalink to &quot;与其他模块的边界&quot;">​</a></h2><ul><li><a href="/frontend/guide/core/">核心知识</a>提供语言、Web 平台、框架和应用开发的通用底座。</li><li><a href="/frontend/guide/engineering/">工程体系</a>负责专项能力进入生产环境后的架构、质量、性能、安全和交付。</li><li>本模块关注独立技术领域的模型、工具和典型实现。</li><li><a href="/frontend/deep-dive/">原理深挖</a>继续研究浏览器、运行时、框架和工具链的内部机制。</li><li><a href="/frontend/practices/">项目实战</a>把专项能力与业务需求、工程约束和技术决策组合起来。</li></ul><h2 id="掌握标准" tabindex="-1">掌握标准 <a class="header-anchor" href="#掌握标准" aria-label="Permalink to &quot;掌握标准&quot;">​</a></h2><ul><li>能判断项目是否真的需要该专题，而不是因为技术新颖而引入。</li><li>能解释专题内不同技术方案的能力边界和主要成本。</li><li>能完成至少一个具有真实约束的实现，而不只是运行演示代码。</li><li>能处理专项技术与框架、工程体系和生产环境之间的连接问题。</li><li>能识别哪些知识是稳定模型，哪些结论依赖具体库、平台或版本。</li></ul>',15)])])}const b=e(r,[["render",l]]);export{p as __pageData,b as default};
